//! libssl's plain setters and getters, generated by the fork's `target/E_gen.py` from a list of
//! exports and the fields they reach (OpenSSL's `ssl_lib.c`). A NULL object reads as 0 or NULL
//! and ignores a setting, where OpenSSL would crash or (for a connection) does the same.

#![allow(clippy::redundant_closure_for_method_calls)]

use core::ptr;

use rustyssl_abi::*;

use super::{conn, ctx};
use crate::ffi::ffi_export;

ffi_export! {
    /// Adds `a` to the options; returns them.
    ///
    /// # Safety
    /// `c` is NULL or a live context; any pointer argument is the application's, stored as
    /// given.
    pub unsafe extern "C" fn rustyssl_private_SSL_CTX_set_options(c: *mut SSL_CTX, a: u64) -> u64
    where failure = 0, library = ERR_LIB_SSL
    {
        // SAFETY: the caller's guarantee.
        let Some(x) = (unsafe { ctx::ctx(c) }) else { return 0 };
        let mut st = x.state();
        st.options |= a;
        st.options
    }
}

/// The connection's options, given to its core too: OpenSSL reads them where it uses them
/// (`SSL_OP_NO_EXTENDED_MASTER_SECRET` set before `SSL_renegotiate`, say).
fn sync_options(st: &mut conn::SslState) -> u64 {
    let options = st.options;
    if let Some(c) = st.drv.tls.as_mut() {
        c.config_mut().options = options;
    }
    options
}

ffi_export! {
    /// Removes `a` from the options; returns them.
    ///
    /// # Safety
    /// `c` is NULL or a live context; any pointer argument is the application's, stored as
    /// given.
    pub unsafe extern "C" fn rustyssl_private_SSL_CTX_clear_options(c: *mut SSL_CTX, a: u64) -> u64
    where failure = 0, library = ERR_LIB_SSL
    {
        // SAFETY: the caller's guarantee.
        let Some(x) = (unsafe { ctx::ctx(c) }) else { return 0 };
        let mut st = x.state();
        st.options &= !a;
        st.options
    }
}

