ffi_export! {
    /// Adds `a` to the options; returns them.
    ///
    /// # Safety
    /// `s` is NULL or a live connection; any pointer argument is the application's, stored as
    /// given.
    pub unsafe extern "C" fn rustyssl_private_SSL_set_options(s: *mut SSL, a: u64) -> u64
    where failure = 0, library = ERR_LIB_SSL
    {
        // SAFETY: the caller's guarantee.
        if unsafe { super::quic::of(s) }.is_some() {
            return super::quic::api::options(s, 0, a);
        }
        // SAFETY: the caller's guarantee.
        let Some(x) = (unsafe { conn::ssl(s) }) else { return 0 };
        let mut st = x.state();
        st.options |= a;
        sync_options(&mut st)
    }
}

